mapper.select:
SELECT i.id, i.title, i.category_id AS categoryId, i.status, i.difficulty, i.question, c.name AS categoryName, a.answer AS myAnswer, a.accuracy AS accuracy, a.solution AS solution, i.created_at AS createdAt, i.updated_at AS updatedAt FROM interview i LEFT JOIN note_category c ON c.id = i.category_id LEFT JOIN interview_ans a ON a.interview_id = i.id
AND i.category_id = #{query.categoryId}
AND i.status = #{query.status}
AND i.difficulty = #{query.difficulty}
AND i.title LIKE CONCAT('%', #{query.keyword}, '%')
ORDER BY i.updated_at DESC

mapper.update:
UPDATE interview_ans
SET answer = #{answer}, accuracy = #{accuracy}, solution = #{solution}, updated_at = NOW()
WHERE interview_id = #{interviewId}

UPDATE interview
SET status = #{status}, updated_at = NOW()
WHERE id = #{interviewId}
